async function QUEUE(rtn, tick) {
  let cint = 0;
  put(cint = await INT(rtn), C_TICK, tick);
  return cint;
}

async function INT(rtn, demon = false, e = 0, c_ = 0, int = 0) {
  e = g.C_TABLE + C_TABLELEN;
  c_ = g.C_TABLE + g.C_INTS;
  for (;;) {
    if (c_ == e) {
      g.C_INTS = g.C_INTS - C_INTLEN;
      demon && (g.C_DEMONS = g.C_DEMONS - C_INTLEN);
      int = g.C_TABLE + g.C_INTS;
      put(int, C_RTN, rtn);
      return int;
    } else if (eq(get(c_, C_RTN), rtn)) {
      return c_;
    }
    c_ = c_ + C_INTLEN;
  }
}

async function CLOCKER() {
  let c_ = 0, e = 0, tick = 0, flg = false;
  if (g.CLOCK_WAIT) {
    g.CLOCK_WAIT = false;
    return false;
  }
  c_ = g.C_TABLE + (g.P_WON ? g.C_INTS : g.C_DEMONS);
  e = g.C_TABLE + C_TABLELEN;
  for (;;) {
    if (c_ == e) {
      if (!(g.GAME_FLAG == 2) && ((g.MOVES = g.MOVES + 1) > 999)) {
        g.MOVES = 0;
      }
      return flg;
    } else if (!(get(c_, C_ENABLED$) == 0)) {
      tick = get(c_, C_TICK);
      if (tick == 0) {
      } else if ((g.GAME_FLAG == 2) && (tick == (-1))) {
        if (await apply(get(c_, C_RTN))) {
          flg = true;
        }
      } else {
        if (g.GAME_FLAG == 2) {
          put(c_, C_TICK, tick = tick - g.C_ELAPSED);
        } else {
          put(c_, C_TICK, tick - 1);
        }
        if (!(tick > 1)) {
          if (g.GAME_FLAG == 2) {
            put(c_, C_TICK, 0);
          }
          if (await apply(get(c_, C_RTN))) {
            flg = true;
          }
        }
      }
    }
    c_ = c_ + C_INTLEN;
  }
}

