async function V_CLIMB_UP(dir = P.UP, obj = false) {
  let x = 0, t = 0;
  if (!obj && g.PRSO) {
    obj = g.PRSO;
  }
  if (t = getPropAddr(g.HERE, dir)) {
    if (obj) {
      x = propSize(t);
      if ((x == NEXIT) || ((x == CEXIT || x == DEXIT || x == UEXIT) && !(await GLOBAL_IN$(g.PRSO, getb(t, 0))))) {
        tell("The ", D(obj), " do");
        if (!(obj == STAIRS)) {
          tell("es");
        }
        tell("n't lead ");
        if (dir == P.UP) {
          tell("up");
        } else {
          tell("down");
        }
        tell("ward.\n");
        return true;
      }
    }
    await DO_WALK(dir);
    return true;
  } else if (!obj) {
    tell(S(g.CANT_GO), "\n");
    return true;
  } else if (obj && (await ZMEMQ(W.WALL, x = getPropAddr(g.PRSO, P.SYNONYM), propSize(x)))) {
    tell("Climbing the walls is to no avail.\n");
    return true;
  } else {
    tell("You can't do that!\n");
    return true;
  }
}

