async function V_DIG() {
  let counter = 0;
  if (!(g.GAME_FLAG == 3)) {
    if (!g.PRSI) {
      g.PRSI = HANDS;
    }
    if (hasFlag(g.PRSI, TOOLBIT)) {
      tell("Digging with the ", D(g.PRSI), " is slow and tedious.\n");
    } else {
      tell("Digging with ");
      await PRINTA(g.PRSI);
      tell(" is silly.\n");
    }
    return true;
  } else if (!(g.PRSO == SAND || g.PRSO == GROUND || g.PRSO == HOLE)) {
    tell("You can't dig in that.\n");
    return true;
  } else if (g.HERE == RIVER_BANK) {
    tell("You dig a small hole, but it quickly fills in with water and sand, almost immediately disappearing.\n");
    return true;
  } else if (!(getProp(g.HERE, P.CAPACITY))) {
    tell("The ground is too hard here.\n");
    return true;
  } else if (g.PRSI == HANDS) {
    tell("I suppose you also excavate tunnels with a teaspoon?!\n");
    return true;
  } else if (g.PRSI == PICK_AXE) {
    tell("Let's face it, for digging in the sand, the axe is cute but ineffective.\n");
    return true;
  } else {
    counter = getProp(g.HERE, P.CAPACITY);
    counter = counter + 1;
    g.THIRST = g.THIRST + 4;
    if ((counter > 5) && !(g.HERE == EX2)) {
      (await JIGS_UP("The walls of the hole collapse around you, smothering you in the shifting sands."));
      return M_FATAL;
    } else if ((counter > 5) && (g.HERE == EX2)) {
      if (counter > 6) {
        tell("Enough already.\n");
        return true;
      }
      tell("You've uncovered what could only be the top of a pyramid. After clearing it away with your hands, you notice a square opening in the top of it.\n");
      putProp(g.HERE, P.CAPACITY, 6);
      putProp(g.HERE, P.LDESC, "You are in the desert, almost out of sight of the encampment to the west. At last, though, you've found the ancient pyramid. The top of the pyramid is clearly exposed and on one of its sides is a square opening.");
      clearFlag(ROCK_LOCK, INVISIBLE);
      move(PYRAMID, g.HERE);
      return g.SCORE = g.SCORE + 25;
    } else {
      tell(S(get(g.DIGGER_LTBL, counter)), "\n");
      return putProp(g.HERE, P.CAPACITY, counter);
    }
  }
}

