async function LIGHT_THE(object, suppress$) {
  setFlag(object, ONBIT);
  setFlag(object, FLAMEBIT);
  if (object == ONE_MATCH) {
    if (hasFlag(MATCHES, OPENBIT)) {
      if (10 > random(100)) {
        tell("Ooops! You didn't remember to close the cover before striking! The matchbook bursts into flames, burning your fingertips.\n");
        move(BURNED_MATCHBOOK, loc(MATCHES));
        setFlag(BURNED_MATCHBOOK, OPENBIT);
        remove(MATCHES);
        remove(MANUAL);
        remove(ONE_MATCH);
        g.MATCH_COUNT = 0;
        suppress$ = true;
      }
    }
  }
  if (!suppress$) {
    tell("The ", D(object), " is now lit.\n");
  }
  if (!g.LIT) {
    g.LIT = await LIT$(g.HERE);
    crlf();
    return await V_LOOK();
  } else {
    return false;
  }
}

async function V_LAMP_OFF() {
  if (!(g.GAME_FLAG == 3)) {
    if (hasFlag(g.PRSO, LIGHTBIT)) {
      if (!(hasFlag(g.PRSO, ONBIT))) {
        tell("It is already off.\n");
      } else {
        clearFlag(g.PRSO, ONBIT);
        if (g.LIT) {
          g.LIT = await LIT$(g.HERE);
        }
        tell("The ", D(g.PRSO), " is now off.\n");
        if (!g.LIT) {
          tell("It is now pitch black.\n");
        }
      }
    } else {
      tell("You can't turn that off.\n");
    }
    return true;
  } else {
    if (hasFlag(g.PRSO, BURNBIT)) {
      if (!(await FLAMING$(g.PRSO))) {
        tell("It is already out.\n");
        return true;
      } else if (g.PRSO == MATCHES || g.PRSO == ONE_MATCH) {
        disable(await INT(I_MATCH_OUT.id));
        await I_MATCH_OUT(true);
        return true;
      } else {
        tell("The ", D(g.PRSO), " is now out.\n");
        return true;
      }
    } else {
      tell("You can't extinguish that.\n");
      return true;
    }
  }
}

async function V_LAMP_ON() {
  if (!(g.GAME_FLAG == 3)) {
    if (hasFlag(g.PRSO, LIGHTBIT)) {
      if (hasFlag(g.PRSO, ONBIT)) {
        tell("It is already on.\n");
      } else {
        setFlag(g.PRSO, ONBIT);
        tell("The ", D(g.PRSO), " is now on.\n");
        if (!g.LIT) {
          g.LIT = await LIT$(g.HERE);
          crlf();
          await V_LOOK();
        }
      }
    } else {
      tell("You can't turn that on.\n");
    }
    return true;
  } else {
    if (hasFlag(g.PRSO, BURNBIT)) {
      if (await FLAMING$(g.PRSO)) {
        if (g.PRSO == ONE_MATCH) {
          tell("One");
        } else {
          tell("It");
        }
        tell(" is already lit.\n");
        return true;
      } else if (((g.PRSO == MANY_MATCHES || g.PRSO == SINGLE_MATCH || g.PRSO == EMPTY_MATCHES) || (g.PRSO == ONE_MATCH)) && (!(loc(ONE_MATCH) == g.WINNER) && !(loc(MATCHES) == g.WINNER))) {
        tell("I see no match here.\n");
        return true;
      } else if ((g.PRSO == MANY_MATCHES || g.PRSO == SINGLE_MATCH || g.PRSO == EMPTY_MATCHES) || (g.PRSO == ONE_MATCH)) {
        if (g.MATCH_COUNT < 1) {
          tell("That's a little tough to do with an empty book of matches.\n");
          return true;
        } else {
          if (!(loc(ONE_MATCH) == g.WINNER)) {
            await MATCH_MOVER();
          }
          tell("You have now lit a match.\n");
          await LIGHT_THE(ONE_MATCH, true);
          if (loc(MATCHES)) {
            return enable(await QUEUE(I_MATCH_OUT.id, 3));
          } else {
            return false;
          }
        }
      } else {
        return await HOW$(g.PRSO);
      }
    } else {
      tell("You can't light that.\n");
      return true;
    }
  }
}

