async function PRINT_CONTENTS(obj) {
  let f = 0, n_ = 0, _1st$ = true, it$ = false, two$ = false;
  if (f = first(obj)) {
    for (;;) {
      n_ = next(f);
      if (_1st$) {
        _1st$ = false;
      } else {
        tell(", ");
        if (!n_) {
          tell("and ");
        }
      }
      await PRINTA(f);
      if (!it$ && !two$) {
        it$ = f;
      } else {
        two$ = true;
        it$ = false;
      }
      f = n_;
      if (!f) {
        if (it$ && !two$) {
          await THIS_IS_IT(it$);
        }
        return true;
      }
    }
  } else {
    return false;
  }
}

async function PRINT_CONT(obj, v$ = false, level = 0) {
  let y = 0, _1st$ = 0, av = 0, str = 0, pv$ = false, inv$ = false;
  if (!(y = first(obj))) {
    return true;
  }
  if ((av = loc(g.WINNER)) && hasFlag(av, VEHBIT)) {
  } else {
    av = false;
  }
  _1st$ = true;
  if (g.WINNER == obj || g.WINNER == loc(obj)) {
    inv$ = true;
  } else {
    for (;;) {
      if (!y) {
        return !_1st$;
      } else if (y == av) {
        pv$ = true;
      } else if (y == g.WINNER) {
      } else if (!(hasFlag(y, INVISIBLE)) && !(hasFlag(y, TOUCHBIT)) && (str = getProp(y, P.FDESC))) {
        if (!(hasFlag(y, NDESCBIT))) {
          tell(S(str), "\n");
        }
        if ((await SEE_INSIDE$(y)) && !(getProp(loc(y), P.DESCFCN)) && first(y)) {
          if (await PRINT_CONT(y, v$, 0)) {
            _1st$ = false;
          }
        }
      }
      y = next(y);
    }
  }
  y = first(obj);
  for (;;) {
    if (!y) {
      if (pv$ && av && first(av)) {
        level = level + 1;
        await PRINT_CONT(av, v$, level);
      }
      return !_1st$;
    } else if (y == av || y == ADVENTURER) {
    } else if (!(hasFlag(y, INVISIBLE)) && (inv$ || hasFlag(y, TOUCHBIT) || !(getProp(y, P.FDESC)))) {
      if (!(hasFlag(y, NDESCBIT))) {
        if (_1st$) {
          if (await FIRSTER(obj, level)) {
            if (level < 0) {
              level = 0;
            }
          }
          level = 1 + level;
          _1st$ = false;
        }
        if (level < 0) {
          level = 0;
        }
        await DESCRIBE_OBJECT(y, v$, level);
      } else if (first(y) && (await SEE_INSIDE$(y))) {
        level = level + 1;
        await PRINT_CONT(y, v$, level);
      }
    }
    y = next(y);
  }
}

