async function GOTO(rm, v$ = true) {
  let lb = hasFlag(rm, RLANDBIT), wloc = loc(g.WINNER), av = false, olit = 0, temp_elapsed = 0;
  if (g.GAME_FLAG == 2) {
    temp_elapsed = get(getProp(g.HERE, P.C_MOVE), g.PRSO - LOW_DIRECTION);
    if (temp_elapsed > 0) {
      g.C_ELAPSED = temp_elapsed;
    } else {
      g.C_ELAPSED = 20;
    }
  }
  olit = g.LIT;
  if (hasFlag(wloc, VEHBIT)) {
    av = getProp(wloc, P.VTYPE);
  }
  if (!lb && !av) {
    await NO_GO_TELL(av, wloc);
    return false;
  } else if (!lb && !(hasFlag(rm, av))) {
    await NO_GO_TELL(av, wloc);
    return false;
  } else if (hasFlag(g.HERE, RLANDBIT) && lb && av && !(av == RLANDBIT) && !(hasFlag(rm, av))) {
    await NO_GO_TELL(av, wloc);
    return false;
  } else if (hasFlag(rm, RMUNGBIT)) {
    tell(S(getProp(rm, P.LDESC)), "\n");
    return false;
  } else {
    if (av) {
      move(wloc, rm);
    } else {
      move(g.WINNER, rm);
    }
    g.HERE = rm;
    g.LIT = await LIT$(g.HERE);
    if (!olit && !g.LIT && (80 > random(100))) {
      (await JIGS_UP("Oh, no! A lurking grue slithered into the room and devoured you."));
      return M_FATAL;
    }
    if (!g.LIT && (g.WINNER == ADVENTURER)) {
      tell("You have moved into a dark place.\n");
      g.P_CONT = false;
    }
    await apply(getProp(g.HERE, P.ACTION), M_ENTER);
    await SCORE_OBJ(rm);
    if (!(g.HERE == rm)) {
      return true;
    } else if (!(ADVENTURER == g.WINNER)) {
      tell("The ", D(g.WINNER), " leaves the room.\n");
    } else if (v$) {
      await V_FIRST_LOOK();
    }
    return true;
  }
}

