async function TBL_TO_INSIDE(obj, tbl, str = 0) {
  let offs = 0, max = 0;
  if (!(hasFlag(obj, SURFACEBIT))) {
    tell("The ", D(obj), " is already open.\n");
    return true;
  }
  if (first(obj)) {
    await OBJS_SLIDE_OFF(obj);
  }
  max = get(tbl, 0);
  if (!str) {
    tell("Opened.");
  } else {
    tell(S(str));
  }
  clearFlag(obj, SURFACEBIT);
  loop1: for (;;) {
    offs = offs + 1;
    if (offs > max) {
      break loop1;
    } else if (!(eq(get(tbl, offs), 0))) {
      move(get(tbl, offs), obj);
      put(tbl, offs, 0);
    }
  }
  if (first(obj)) {
    tell(" Opening the ", D(obj), " reveals ");
    await PRINT_CONTENTS(obj);
    tell(".");
  }
  return crlf();
}

async function INSIDE_OBJ_TO(tbl, obj) {
  let offs = 0, f = 0, n_ = 0;
  if (hasFlag(obj, SURFACEBIT)) {
    tell("The ", D(obj), " is already closed.\n");
    return true;
  }
  setFlag(obj, SURFACEBIT);
  tell("Closed.\n");
  if (!(first(obj))) {
    return true;
  }
  f = first(obj);
  for (;;) {
    if (!f) {
      return true;
    } else {
      n_ = f;
      f = next(n_);
      remove(n_);
      loop2: for (;;) {
        offs = offs + 1;
        if (eq(get(tbl, offs), 0)) {
          put(tbl, offs, n_);
          break loop2;
        }
      }
    }
  }
}

