async function SOUTH_DOOR_F() {
  if (isVerb(V.UNLOCK)) {
    if (!g.DOOR_LOCKED) {
      tell("The door is already unlocked, or don't you remember!\n");
      return true;
    } else if (g.PRSI == KEY) {
      tell("Fortunately for you, the key was the correct one and the door unlocks.\n");
      g.DOOR_LOCKED = false;
      return true;
    } else {
      tell("That wasn't a very smart thing to try; ", D(g.PRSI), "s are rarely used in unlocking doors.\n");
      return true;
    }
  } else if (isVerb(V.LOCK)) {
    if (g.DOOR_LOCKED) {
      tell("The door is sufficiently locked without your help.");
      return true;
    } else if (g.PRSI == KEY) {
      tell("Very well. The door is now locked.\n");
      return g.DOOR_LOCKED = true;
    } else {
      tell("Dear, dear. What will you think of next?\n");
      return true;
    }
  } else if (isVerb(V.OPEN) && g.DOOR_LOCKED) {
    tell("It seems to be locked!\n");
    return true;
  } else if (isVerb(V.KNOCK)) {
    if (hasFlag(g.PRSO, OPENBIT)) {
      tell("Why are you knocking on an open door?\n");
      return true;
    } else {
      tell("Nobody answers.\n");
      return true;
    }
  } else if (isVerb(V.MUNG)) {
    tell("Besides hurting your shoulder, the effort gets you nowhere.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    tell("You hear nothing through the door.\n");
    return true;
  } else {
    return false;
  }
}

