      clearFlag(PF_KEY, TRYTAKEBIT);
      setFlag(PF_KEY, TOUCHBIT);
      tell("With a spray of dust and a loud clank, a piece of metal leaps from the crevice and affixes itself to the magnet. It is a steel key! With a tug, you remove the key from the magnet.\n");
