async function CHEMICAL_FLUID_F() {
  if (isVerb(V.EAT, V.DRINK)) {
    return (await JIGS_UP("Mmmmm....that tasted just like delicious poisonous chemicals!"));
  } else if (isVerb(V.PUT, V.POUR, V.POUR_IN, V.POUR_ON)) {
    if (!(loc(FLASK) == g.PLAYER)) {
      tell("You're not holding the flask!\n");
      return true;
    } else if (g.PRSI == PF_CANTEEN) {
      await WORTHLESS_ACTION();
      return true;
    }
    remove(CHEMICAL_FLUID);
    if (!g.PRSI) {
      g.PRSI = GROUND;
    }
    if (g.CHEMICAL_FLAG == 8 || g.CHEMICAL_FLAG == 9) {
      if (await DISSOLVABLE$(g.PRSI)) {
        if (g.PRSI == g.SPOUT_PLACED) {
          g.SPOUT_PLACED = GROUND;
        }
        remove(g.PRSI);
        tell("The ", D(g.PRSI), " dissolves right before your eyes!\n");
        return true;
      } else if ((CREVICE == g.PRSI) && !(hasFlag(PF_KEY, TOUCHBIT))) {
        if (hasFlag(PF_KEY, INVISIBLE)) {
          tell("A puff of smoke rises from the crevice.\n");
        } else {
          tell("Although the chemical has no effect on the crevice, it does seem to have dissolved the key that was lying in it.\n");
        }
        remove(PF_KEY);
        setFlag(PF_KEY, TOUCHBIT);
        return clearFlag(PF_KEY, INVISIBLE);
      } else if (g.PRSI == ME || g.PRSI == ADVENTURER || g.PRSI == HANDS) {
        return (await JIGS_UP("Have you always had this desire to see melting flesh?"));
      } else if ((g.PRSI == FLOYD) && hasFlag(FLOYD, RLANDBIT)) {
        tell("Floyd yelps. \"Hey, cut it out! That stuff burns!\"\n");
        return true;
      } else if (await MUNGABLE$(g.PRSI)) {
        setFlag(g.PRSI, RMUNGBIT);
        if (g.PRSI == CHRONOMETER) {
          g.MUNGED_TIME = g.INTERNAL_MOVES;
        }
        tell("The ", D(g.PRSI), " seems to undergo some damage as a result of your action.\n");
        return true;
      } else {
        return await CHEMICAL_POURS();
      }
    } else {
      return await CHEMICAL_POURS();
    }
  } else {
    return false;
  }
}

async function CHEMICAL_POURS() {
  tell("The chemical pours all over the ", D(g.PRSI), ", making quite a mess.\n");
  return true;
}

async function DISSOLVABLE$(obj) {
  if (obj == PF_KEY || obj == GOOD_BEDISTOR || obj == OLD_BATTERY) {
    return true;
  } else if (obj == MEGAFUSE_B || obj == MEGAFUSE_K || obj == CRACKED_BOARD) {
    return true;
  } else {
    return false;
  }
}

async function MUNGABLE$(obj) {
  if (obj == LASER || obj == LASER_DIAL || obj == PADLOCK) {
    return true;
  } else if (obj == CHEMICAL_DISPENSER || obj == CHRONOMETER) {
    return true;
  } else {
    return false;
  }
}

async function END_PLANETFALL() {
  if (g.FLOYD_INTRODUCED) {
    tell("Floyd bounces after you. \"Hey, wait for Floyd!");
  } else {
    tell("A robot comes bounding across the ladder after you. \"Hi, I'm Floyd! Oh, boy, I haven't had any friends to play with in thousands of years!");
  }
  tell("\" He seems to hear something inaudible to you. \"What? Planetfall excerpt is over? Already? But we haven't even played one game of Hider-and-Seeker!\" The robot looks up at you, and you can see tears of oil beginning to form in his wide eyes. \"You'll buy the real Planetfall and come back and play with Floyd, won't you?\" Then the robot, and your surroundings, begin fading away...\n\n");
  return await FINISH();
}

