async function DESCRIBE_HOLE_FCN(rarg) {
  let depth = 0;
  let $1, $2, $3, $4, $5;
  if (rarg == M_LOOK) {
    tell(S(getProp(g.HERE, P.LDESC)));
    depth = getProp(g.HERE, P.CAPACITY);
    if ((depth > 5) && (g.HERE == EX2)) {
      crlf();
      return true;
    } else if (depth > 0) {
      tell(" There's a", S(get(g.DESC_HOLE_LTBL, depth)), " in the sand, a remnant of your excavation attempts.");
    }
    if (g.HERE == ENDLESS_DESERT) {
      if (g.THIRST > 300) {
        tell(" ");
        $1 = await PICK_ONE(g.SPACE_TALES_LTBL);
        tell(S($1));
      } else if (50 > random(100)) {
        if (35 > random(100)) {
          tell(" ");
          $2 = await PICK_ONE(g.SPACE_TALES_LTBL);
          tell(S($2));
        } else {
          tell(" ");
          $3 = await PICK_ONE(g.MIRAGE_LTBL);
          tell(S($3));
        }
      }
    } else if (getProp(g.HERE, P.TVALUE)) {
      if (g.THIRST > 300) {
        tell(" ");
        $4 = await PICK_ONE(g.MIRAGE_LTBL);
        tell(S($4));
      } else {
        if (20 > random(100)) {
          tell(" ");
          $5 = await PICK_ONE(g.MIRAGE_LTBL);
          tell(S($5));
        }
      }
    }
    crlf();
    return true;
  } else if (rarg == M_ENTER) {
    g.THIRST = g.THIRST + 15;
    return false;
  } else if (rarg == M_BEG) {
    if ((loc(g.WINNER) == COT) && isVerb(V.WALK)) {
      tell("Better get out of the cot first.\n");
      return true;
    }
    g.THIRST = g.THIRST + 3;
    return false;
  } else {
    return false;
  }
}

