async function COT_FCN(rarg = M_OBJECT) {
  let f = 0;
  if (isVerb(V.WALK, V.THROUGH) && eq(loc(g.WINNER), COT)) {
    tell("You'd better get out of the cot first.\n");
    return M_FATAL;
  } else if (!(rarg == M_OBJECT)) {
    return false;
  } else if (g.PRSO == COT) {
    f = first(COT);
    if (isVerb(V.TAKE, V.PUT, V.PUT_ON)) {
      tell("It's too bulky and unstable a structure to be carrying around.\n");
      return true;
    } else if (isVerb(V.CLIMB_ON, V.CLIMB_UP)) {
      if (loc(g.WINNER) == COT) {
        tell("Where do you think you are?\n");
      } else {
        tell("This is no time for sitting down on the job, especially after what you've been through to get here!\n");
      }
      return true;
    } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
      tell("It's just an army cot.");
      if (f && (f == g.WINNER)) {
        tell(" And you're in it!");
      } else if (f) {
        tell(" Sitting on the cot ");
        if ((await CCOUNT(COT)) > 1) {
          tell("are ");
        } else {
          tell("is ");
        }
        await PRINT_CONTENTS(COT);
        tell(".");
      }
      crlf();
      return true;
    } else if (isVerb(V.FOLD, V.CLOSE)) {
      if (!f) {
        tell("Folded.\n");
        move(FOLDED_COT, loc(COT));
        remove(COT);
        await THIS_IS_IT(FOLDED_COT);
        return true;
      } else if (f == g.WINNER) {
        tell("Don't you think it would be wise to get out of the cot first? Or are you waiting for a valet to help?\n");
        return true;
      } else if (f) {
        tell("You'd better take everything off of it first.\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.OPEN, V.UNFOLD)) {
      tell("It's already unfolded.\n");
      return true;
    } else if (isVerb(V.DROP) && eq(loc(g.WINNER), COT)) {
      await PERFORM(V.DISEMBARK, COT);
      return true;
    } else {
      return false;
    }
  } else if (g.PRSO == FOLDED_COT) {
    if (isVerb(V.OPEN, V.UNFOLD)) {
      if (!(loc(FOLDED_COT) == g.HERE)) {
        tell("Better put it down on the ground first.\n");
        return true;
      } else {
        tell("Unfolded.\n");
        move(COT, loc(FOLDED_COT));
        remove(FOLDED_COT);
        await THIS_IS_IT(COT);
        return true;
      }
    } else if (isVerb(V.FOLD, V.CLOSE)) {
      tell("Hmmm. Looks like you beat yourself to it. It's already folded up.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

