async function CANTEEN_FCN() {
  if (isVerb(V.SHAKE)) {
    if (!(hasFlag(CANTEEN, OPENBIT))) {
      if ((loc(WATER) == CANTEEN) && (g.WATER_LEFT > 9)) {
        tell("Some water sloshes around inside.\n");
        return true;
      } else if (g.SAND_FILLED) {
        tell("Some sand shakes around inside.\n");
        return true;
      } else {
        tell("It's empty.\n");
        return true;
      }
    } else if (loc(WATER) == CANTEEN) {
      tell("All the water spills out and quickly evaporates. Another smart move.\n");
      remove(WATER);
      g.WATER_LEFT = 0;
      return true;
    } else if (g.SAND_FILLED) {
      tell("You empty the canteen of most of the sand.\n");
      g.SAND_FILLED = false;
      remove(C_SAND);
      setFlag(C_SAND, NDESCBIT);
      return true;
    } else {
      tell("Okay, but shaking an empty canteen will get you nowhere fast.\n");
      return true;
    }
  } else if (isVerb(V.FILL) && (g.PRSI == SAND)) {
    if (!(getProp(g.HERE, P.VTYPE))) {
      tell("I see no sand here.\n");
    } else if (!(hasFlag(CANTEEN, OPENBIT))) {
      tell("It would help if you opened the canteen first.\n");
      return true;
    } else {
      tell("Okay. The canteen has been filled with sand.");
      if (g.WATER_LEFT) {
        g.WATER_LEFT = 0;
        remove(WATER);
        tell(" So much for the water that was left in it.");
      }
      crlf();
      g.SANDY_CANTEEN = true;
      g.SAND_FILLED = true;
      move(C_SAND, CANTEEN);
      clearFlag(C_SAND, NDESCBIT);
    }
    return true;
  } else if ((g.PRSI == CANTEEN) && isVerb(V.PUT) && !(g.PRSO == SAND || g.PRSO == GLOBAL_WATER || g.PRSO == C_SAND)) {
    tell("That would void the manufacturer's warranty on the canteen.\n");
    return true;
  } else {
    return false;
  }
}

async function MIRAGES_F() {
  tell("Come on! This life you're leading is bad enough -- don't waste your life on illusions.\n");
  return true;
}

async function DESERT_EXIT_FCN(rarg) {
  let end_of_tbl = 26, offs = 0, new_room = false, old_desert = 0;
  if (rarg == M_END) {
    if (isVerb(V.DROP) && (33 > random(100)) && !g.TOLD_IT) {
      await TABLE_TO_DESERT(g.DESERT_LOC);
      remove(g.PRSO);
      tell("A brief but strong gust of wind comes up off a dune, whipping sand in your face, blinding you for long enough to lose track of the ", D(g.PRSO), ".\n");
      g.TOLD_IT = true;
    }
    return true;
  } else if (rarg == M_LOOK) {
    await DESCRIBE_HOLE_FCN(M_LOOK);
    g.TOLD_IT = false;
    return true;
  } else if (!(rarg == M_BEG)) {
    return false;
  } else if (!(isVerb(V.WALK)) || (g.PRSO == P.UP || g.PRSO == P.DOWN)) {
    g.TOLD_IT = false;
    return false;
  }
  g.TOLD_IT = false;
  g.THIRST = g.THIRST + 15;
  old_desert = g.DESERT_LOC;
  await CHANGE_DESERT_POSITION();
  loop1: for (;;) {
    if (offs == end_of_tbl) {
      break loop1;
    } else {
      if (g.DESERT_LOC == get(g.REENTRY_TBL, offs)) {
        new_room = get(g.REENTRY_TBL, offs + 1);
        break loop1;
      } else {
        offs = offs + 2;
      }
    }
  }
  await DESERT_TO_TABLE(old_desert);
  await PROP_TO_TBL(old_desert);
  if (!new_room) {
    clearFlag(g.HERE, TOUCHBIT);
    new_room = ENDLESS_DESERT;
    await TABLE_TO_DESERT(g.DESERT_LOC);
    await TBL_TO_PROP(g.DESERT_LOC);
  } else {
    await TBL_TO_PROP(old_desert);
  }
  await GOTO(new_room);
  return true;
}

async function DESERT_TO_TABLE(sloc) {
  let tbl = 0, cnt = 0, f = first(ENDLESS_DESERT), n_ = 0;
  tbl = g.DESERT_TABLE;
  for (;;) {
    if (f) {
      n_ = next(f);
    } else {
      return true;
    }
    if (f == g.WINNER) {
    } else if (hasFlag(f, TAKEBIT)) {
      loop2: for (;;) {
        if (eq(get(tbl, cnt), 0)) {
          put(tbl, cnt, sloc);
          put(tbl, cnt + 1, f);
          cnt = cnt + 2;
          remove(f);
          break loop2;
        } else {
          cnt = cnt + 2;
        }
      }
    }
    f = n_;
  }
}

async function TABLE_TO_DESERT(sloc) {
  let tbl = 0, cnt = 0;
  tbl = g.DESERT_TABLE;
  for (;;) {
    if (!(cnt < 100)) {
      return true;
    } else if (eq(get(tbl, cnt), sloc)) {
      put(tbl, cnt, 0);
      move(get(tbl, cnt + 1), ENDLESS_DESERT);
    }
    cnt = cnt + 2;
  }
}

async function CHANGE_DESERT_POSITION() {
  g.DESERT_HACK = g.DESERT_HACK + 1;
  if (g.DESERT_HACK == 10) {
    tell("WARNING: The Surgeon General has determined that wandering about like this is dangerous to your health.\n");
    crlf();
  } else if (g.DESERT_HACK == 20) {
    if (await ROB_HIM_BLIND()) {
      tell("You start dropping things to lighten your load. Before you know it, you're empty-handed. A gust of wind comes up off the dune before you, covering over what you've dropped. So much for that.\n");
      crlf();
    }
  }
  if (g.PRSO == P.NORTH) {
    g.DESERT_LOC = g.DESERT_LOC - 50;
    return await FIX_LON_LAT(0, 2);
  } else if (g.PRSO == P.NE) {
    g.DESERT_LOC = g.DESERT_LOC - 49;
    return await FIX_LON_LAT(2, 2);
  } else if (g.PRSO == P.EAST) {
    g.DESERT_LOC = g.DESERT_LOC + 1;
    return await FIX_LON_LAT(2, 0);
  } else if (g.PRSO == P.SE) {
    g.DESERT_LOC = g.DESERT_LOC + 51;
    return await FIX_LON_LAT(2, -2);
  } else if (g.PRSO == P.SOUTH) {
    g.DESERT_LOC = g.DESERT_LOC + 50;
    return await FIX_LON_LAT(0, -2);
  } else if (g.PRSO == P.SW) {
    g.DESERT_LOC = g.DESERT_LOC + 49;
    return await FIX_LON_LAT(-2, -2);
  } else if (g.PRSO == P.WEST) {
    g.DESERT_LOC = g.DESERT_LOC - 1;
    return await FIX_LON_LAT(-2, 0);
  } else if (g.PRSO == P.NW) {
    g.DESERT_LOC = g.DESERT_LOC - 51;
    return await FIX_LON_LAT(-2, 2);
  } else {
    return false;
  }
}

async function FIX_LON_LAT(inc_lon, inc_lat) {
  if (inc_lon) {
    g.SECS_LON = g.SECS_LON + inc_lon;
    if (g.SECS_LON > 60) {
      g.SECS_LON = 1;
      g.MINS_LON = g.MINS_LON + 1;
      if (g.MINS_LON > 59) {
        g.MINS_LON = 0;
        g.DEGS_LON = g.DEGS_LON + 1;
      }
    } else if (g.SECS_LON < 1) {
      g.SECS_LON = 59;
      g.MINS_LON = g.MINS_LON - 1;
      if (g.MINS_LON < 0) {
        g.MINS_LON = 59;
        g.DEGS_LON = g.DEGS_LON - 1;
      }
    }
  }
  if (inc_lat) {
    g.SECS_LAT = g.SECS_LAT + inc_lat;
    if (g.SECS_LAT > 60) {
      g.SECS_LAT = 1;
      g.MINS_LAT = g.MINS_LAT + 1;
      if (g.MINS_LAT > 59) {
        g.MINS_LAT = 0;
        return g.DEGS_LAT = g.DEGS_LAT + 1;
      } else {
        return false;
      }
    } else if (g.SECS_LAT < 1) {
      g.SECS_LAT = 59;
      g.MINS_LAT = g.MINS_LAT - 1;
      if (g.MINS_LAT < 0) {
        g.MINS_LAT = 59;
        return g.DEGS_LAT = g.DEGS_LAT - 1;
      } else {
        return false;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function ROB_HIM_BLIND() {
  let f = 0, n_ = 0, flg = false;
  f = first(g.WINNER);
  loop1: for (;;) {
    if (!f) {
      break loop1;
    } else {
      n_ = f;
      f = next(n_);
      remove(n_);
      flg = true;
    }
  }
  return flg;
}

async function PROP_TO_TBL(sloc) {
  let tbl = g.PROP_TBL, cnt = 0, dug = 0;
  dug = getProp(g.HERE, P.CAPACITY);
  if (dug == 0) {
    return false;
  }
  for (;;) {
    if (eq(get(tbl, cnt), 0)) {
      put(tbl, cnt, sloc);
      put(tbl, cnt + 1, dug);
      putProp(g.HERE, P.CAPACITY, 0);
      cnt = cnt + 2;
      return true;
    } else {
      cnt = cnt + 2;
    }
  }
}

async function TBL_TO_PROP(sloc) {
  let tbl = g.PROP_TBL, cnt = 0;
  for (;;) {
    if (!(cnt < 120)) {
      return true;
    } else if (eq(get(tbl, cnt), sloc)) {
      put(tbl, cnt, 0);
      putProp(g.HERE, P.CAPACITY, get(tbl, cnt + 1));
    }
    cnt = cnt + 2;
  }
}

async function WEAR_THE_SACK() {
  let on_in$ = 0;
  (on_in$ = "in");
  if (KNAPSACK == g.PRSO) {
    if (isVerb(V.WEAR)) {
      if (!(loc(KNAPSACK) == g.WINNER)) {
        if (eq(await ITAKE(), M_FATAL, false)) {
          return true;
        } else {
          if (!(g.PRSI == NASTY_CROC)) {
            tell("(taken)\n");
          } else {
            tell("(wearing it)\n");
          }
        }
      }
      tell("You swing the knapsack over your shoulders and it settles on your back as its cover flap closes.\n");
      clearFlag(KNAPSACK, OPENBIT);
      setFlag(KNAPSACK, WEARBIT);
      return await THIS_IS_IT(KNAPSACK);
    } else if (isVerb(V.PUT, V.PUT_ON) && (g.PRSI == ME)) {
      await PERFORM(V.WEAR, KNAPSACK);
      await THIS_IS_IT(KNAPSACK);
      return true;
    } else if (isVerb(V.PUT, V.PUT_ON) && g.PRSI) {
      if (g.PRSI == KNAPSACK) {
        tell("Sure. Just like a Klein Bottle, eh?\n");
        return true;
      } else if (g.PRSI == CRACK) {
        await PERFORM(g.PRSA, g.PRSO, GROUND);
        return true;
      } else if (g.PRSI == FOLDED_COT) {
        tell("Bizarre!\n");
        return true;
      } else if (!(hasFlag(KNAPSACK, WEARBIT))) {
        return false;
      } else {
        if ((g.PRSI == GROUND) && getProp(g.HERE, P.VTYPE) && !(await IN_A_TENT$())) {
          g.PRSI = SAND;
        }
        if (hasFlag(g.PRSI, SURFACEBIT)) {
          (on_in$ = "on");
        }
        tell("You take the knapsack off and place it ", S(on_in$), " the ", D(g.PRSI), ". As it settles ", S(on_in$), " the ", D(g.PRSI), ", the cover flaps open.\n");
        clearFlag(KNAPSACK, WEARBIT);
        setFlag(KNAPSACK, OPENBIT);
        if (g.PRSI == GROUND || g.PRSI == SAND) {
          await IDROP();
        } else {
          move(KNAPSACK, g.PRSI);
        }
        await THIS_IS_IT(KNAPSACK);
        return true;
      }
    } else if (isVerb(V.OPEN) && hasFlag(KNAPSACK, WEARBIT)) {
      tell("You reach around behind to lift the flap on the top of the knapsack, but it keeps falling back down.\n");
      await THIS_IS_IT(KNAPSACK);
      return true;
    } else if (isVerb(V.SHAKE) && hasFlag(KNAPSACK, WEARBIT)) {
      tell("Better take it off first. Unless you want to do a few headstands.\n");
      await THIS_IS_IT(KNAPSACK);
      return true;
    } else if (isVerb(V.FIND)) {
      if (hasFlag(KNAPSACK, WEARBIT)) {
        tell("It's on your back!\n");
        return true;
      } else {
        return false;
      }
    } else if (isVerb(V.LOOK_INSIDE, V.EXAMINE) && hasFlag(KNAPSACK, WEARBIT)) {
      tell("Your neck doesn't crane back that far. Better take it off first.\n");
      await THIS_IS_IT(KNAPSACK);
      return true;
    } else if (isVerb(V.DISEMBARK, V.DROP, V.TAKE_OFF)) {
      if (!(hasFlag(KNAPSACK, WEARBIT))) {
        tell("You aren't wearing it!\n");
        return true;
      } else {
        tell("You take the knapsack off and place it down. As it settles, the cover flaps open.\n");
        clearFlag(KNAPSACK, WEARBIT);
        setFlag(KNAPSACK, OPENBIT);
        await IDROP();
        await THIS_IS_IT(KNAPSACK);
        return true;
      }
    } else if (isVerb(V.TAKE)) {
      if (hasFlag(g.PRSO, WEARBIT) && (eq(get(g.P_VTBL, 0), W.REMOVE) || (g.PRSI == ME))) {
        await PERFORM(V.DISEMBARK, g.PRSO);
        return true;
      } else {
        if (!(hasFlag(g.PRSO, WEARBIT))) {
          await PERFORM(V.WEAR, g.PRSO, NASTY_CROC);
          return true;
        } else {
          tell("You already have it.\n");
          return true;
        }
      }
    } else {
      return false;
    }
  } else if (KNAPSACK == g.PRSI) {
    if (isVerb(V.PUT)) {
      if (await FLAMING$(g.PRSO)) {
        tell("Don't you think you should put out the ", D(g.PRSO), " first?\n");
        return true;
      } else if (g.PRSO == SHOVEL || g.PRSO == CRATE) {
        tell("That's like trying to fit a Beethoven Symphony into a music box.\n");
        return true;
      } else if (g.PRSO == SAND || g.PRSO == WATER || g.PRSO == GLOBAL_WATER) {
        tell("It would only seep through the roughly-stitched seams, so why bother?\n");
        return true;
      } else {
        setFlag(g.PRSO, TOUCHBIT);
        return false;
      }
    } else if (isVerb(V.TAKE)) {
      if (hasFlag(KNAPSACK, OPENBIT)) {
        return false;
      } else if (hasFlag(KNAPSACK, WEARBIT)) {
        tell("Your arms don't reach back that far, and groping around in the sack isn't the best of ideas. It would help if you took it off first.\n");
        await THIS_IS_IT(KNAPSACK);
        return true;
      } else {
        tell("The knapsack isn't open.\n");
        await THIS_IS_IT(KNAPSACK);
        return true;
      }
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function CRATE_FCN() {
  let flg = false;
  if (!(g.GAME_FLAG == 3)) {
    tell("I don't know the word \"crate\".\n");
    g.P_WON = false;
    return true;
  }
  if (isVerb(V.READ, V.EXAMINE) && ((loc(CRATE) == loc(g.WINNER)) || (loc(CRATE) == g.HERE) || (loc(CRATE) == g.WINNER) || eq(loc(CRATE), loc(g.WINNER)) || eq(loc(CRATE), g.WINNER) || ((loc(CRATE) == KNAPSACK) && eq(loc(KNAPSACK), g.HERE)))) {
    tell("The crate is slightly beaten up from the landing, but it seems to have held together fairly well. There's a small label on it that says \"This crate contains 1 (one) black box (tm).\"\n");
    return true;
  } else if (isVerb(V.EXAMINE) && (loc(CRATE) == GLOBAL_OBJECTS) && !(await IN_A_TENT$()) && (g.MOVES > 4)) {
    tell("It's coming down, and it looks like it should land near you!\n");
    return true;
  } else if (isVerb(V.EXAMINE) && (loc(CRATE) == GLOBAL_OBJECTS) && (await IN_A_TENT$())) {
    tell("I think you've got crates on the mind!\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE) && !(loc(CRATE) == GLOBAL_OBJECTS) && hasFlag(CRATE, SURFACEBIT)) {
    tell("The crate is closed.\n");
    return true;
  } else if (isVerb(V.MUNG) && !(loc(CRATE) == GLOBAL_OBJECTS)) {
    if (g.PRSI == SHOVEL || g.PRSI == PICK_AXE) {
      tell("Wood chips fly from the crate, hurtling into the sand all around, as the crate suffers your frenzied attack. The defenseless packing crate looks as if to flee but before it can react (growing legs is a time-consuming task) there is nothing left of it but a mere memory. (You really should seek some psychological counselling.)\n");
      if (!(hasFlag(BLACK_BOX, TOUCHBIT))) {
        move(BLACK_BOX, g.HERE);
        setFlag(BLACK_BOX, RMUNGBIT);
      }
      remove(g.PRSO);
      g.P_IT_LOC = false;
      return true;
    } else {
      return false;
    }
  } else if (!(loc(CRATE) == GLOBAL_OBJECTS) && (isVerb(V.BURN) || (isVerb(V.DROP) && (g.PRSI == CRATE) && (await FLAMING$(g.PRSO))))) {
    tell("Well, who would have thought it? The crate catches fire quickly, the flames leaping about in mad abandon, gaily changing color as the heat becomes more and more intense. You hear a sizzling");
    if (!(hasFlag(BLACK_BOX, TOUCHBIT))) {
      (await JIGS_UP("... followed by an explosion which takes place right before your face. Needless to say, your body didn't appreciate it."));
    } else {
      tell(" as the crate consumes itself in gleeful merriment.\n");
      remove(CRATE);
      g.P_IT_LOC = false;
    }
    return true;
  } else if (isVerb(V.STAND_UNDER)) {
    return false;
  } else if (isVerb(V.BOARD) && !(loc(CRATE) == GLOBAL_OBJECTS)) {
    tell("You couldn't fit in there unless you put yourself through a trash compacter.\n");
    return true;
  } else if (loc(CRATE) == GLOBAL_OBJECTS) {
    tell("Hey, give it a chance to get here. I know you're impatient to get on with this, but be reasonable!\n");
    return true;
  } else if (isVerb(V.OPEN)) {
    (await TBL_TO_INSIDE(CRATE, g.CRATE_TBL, "The crate opens slowly, the boards creaking with the strain."));
    return true;
  } else if (isVerb(V.CLOSE) && !(hasFlag(CRATE, SURFACEBIT))) {
    await INSIDE_OBJ_TO(g.CRATE_TBL, CRATE);
    return true;
  } else if (isVerb(V.SHAKE)) {
    if (!(get(g.CRATE_TBL, 1) == 0)) {
      tell("Hmm. Something's in there.\n");
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function BOX_OPENER_FCN() {
  if (isVerb(V.OPEN)) {
    tell("To do that to the ", D(BLACK_BOX), " would most probably ruin the delicate equipment inside.\n");
    return true;
  } else if (isVerb(V.CLOSE)) {
    tell("I didn't know it was open.\n");
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell(S(getProp(g.PRSO, P.TEXT)), "\n");
    return true;
  } else if (isVerb(V.LAMP_ON)) {
    await PERFORM(V.PUSH, BUTTON);
    return true;
  } else if (isVerb(V.LAMP_OFF)) {
    tell("It turns itself off after each button press.\n");
    return true;
  } else if (isVerb(V.THROW, V.MUNG, V.ATTACK, V.SHAKE) && (g.PRSO == BLACK_BOX)) {
    tell("Rattle, rattle, jostle, crunch. Oh oh...\n");
    setFlag(BLACK_BOX, RMUNGBIT);
    if (isVerb(V.THROW)) {
      move(g.PRSO, g.HERE);
    }
    return true;
  } else {
    return false;
  }
}

async function PRESS_BUTTON_FCN() {
  let offs = (-3), lat_s = 0, lon_s = 0, h_ck = 0;
  let $1;
  if (isVerb(V.PUSH)) {
    if (hasFlag(BLACK_BOX, RMUNGBIT)) {
      $1 = await PICK_ONE(g.NOISES_LTBL);
      tell(S($1));
      tell("!\n");
      return true;
    } else if (g.HERE == ENDLESS_DESERT) {
      tell("The box comes to life, its L.E.D.s lighting, and then flashes ", N(g.DEGS_LAT));
      tell(" degree");
      if (!(g.DEGS_LAT == 1)) {
        tell("s");
      }
      tell(" ", N(g.MINS_LAT), " minute");
      if (!(g.MINS_LAT == 1)) {
        tell("s");
      }
      tell(" ", N(g.SECS_LAT), " seconds N latitude, ");
      tell(N(g.DEGS_LON));
      tell(" degree");
      if (!(g.DEGS_LON == 1)) {
        tell("s");
      }
      tell(" ", N(g.MINS_LON), " minute");
      if (!(g.MINS_LON == 1)) {
        tell("s");
      }
      tell(" ", N(g.SECS_LON), " seconds E longitude.\n");
      return true;
    } else {
      if (g.HERE == TENT) {
        h_ck = P2;
      } else if (g.HERE == TENT2) {
        h_ck = P7;
      } else if (g.HERE == SUPPLY_TENT) {
        h_ck = P4;
      } else {
        h_ck = g.HERE;
      }
      loop1: for (;;) {
        offs = offs + 3;
        if (offs > 54) {
          break loop1;
        } else {
          if (h_ck == get(g.MAP_TBL, offs)) {
            lon_s = get(g.MAP_TBL, offs + 1);
            lat_s = get(g.MAP_TBL, offs + 2);
            break loop1;
          }
        }
      }
      tell("The box comes to life, its L.E.D.s lighting, and then flashes 24 degrees 11 minutes ", N(lat_s), " seconds N latitude, 32 degrees 12 minutes ", N(lon_s), " seconds E longitude.\n");
      return true;
    }
  } else if (isVerb(V.FIND)) {
    tell("It's on the top of the box.\n");
    return true;
  } else {
    return false;
  }
}

async function DIASMBIGUATE_FCN(object) {
  if (loc(ONE_MATCH) == g.WINNER) {
    return ONE_MATCH;
  } else if (loc(MATCHES) == g.WINNER) {
    if (!(hasFlag(MATCHES, OPENBIT))) {
      tell("(opening matchbook first)\n");
      setFlag(MATCHES, OPENBIT);
    }
    if (g.MATCH_COUNT > 1) {
      return MANY_MATCHES;
    } else if (g.MATCH_COUNT == 1) {
      return SINGLE_MATCH;
    } else {
      return EMPTY_MATCHES;
    }
  } else {
    return ONE_MATCH;
  }
}

async function I_GINANDTONIC() {
  if (g.THIRST > 400) {
    return (await JIGS_UP("Like a grape, left out in the sun too long, you turn into a raisin for lack of water."));
  } else if ((g.THIRST > 380) && (g.THIRST < 387)) {
    tell("If you don't drink something, and now, you're gonna be history.\n");
    return true;
  } else if ((g.THIRST > 300) && (g.THIRST < 317)) {
    if (!(g.HERE == TENT || g.HERE == TENT2 || g.HERE == SUPPLY_TENT)) {
      tell("You'd better drink something, and soon!\n");
      return true;
    } else {
      tell("You wipe your fevered brow.\n");
      return true;
    }
  } else if ((g.THIRST > 200) && (g.THIRST < 217)) {
    if (!(g.HERE == TENT || g.HERE == TENT2 || g.HERE == SUPPLY_TENT)) {
      tell("You scowl at the sun, cursing its searing heat.\n");
      return true;
    } else {
      tell("Even in the tent the heat starts to get to you.\n");
      return true;
    }
  } else {
    return false;
  }
}

async function I_MATCH_OUT(blown$ = 0) {
  let flg = false;
  if (hasFlag(ONE_MATCH, FLAMEBIT)) {
    if (!blown$) {
      tell("Your match went out.");
    } else if (blown$) {
      tell("You blow out the match and toss it aside.");
    }
    flg = true;
  }
  clearFlag(ONE_MATCH, ONBIT);
  clearFlag(ONE_MATCH, FLAMEBIT);
  clearFlag(MANY_MATCHES, FLAMEBIT);
  if ((loc(ONE_MATCH) == g.WINNER) && !blown$) {
    tell(" And it burned your fingers, too! You drop it. ");
    await BUT_WHERE$();
    flg = false;
  }
  move(ONE_MATCH, GLOBAL_OBJECTS);
  if (g.LIT) {
    g.LIT = await LIT$(g.HERE);
  }
  if (!(g.LIT = await LIT$(g.HERE))) {
    tell(" It is now pitch black.");
    flg = true;
  }
  if (flg) {
    return crlf();
  } else {
    return false;
  }
}

async function I_GROWL() {
  g.HUNGER = g.HUNGER + 1;
  if ((g.HUNGER > 70) && (g.HUNGER < 73)) {
    tell("Your stomach growls in hunger.\n");
    return true;
  } else if ((g.HUNGER > 100) && (g.HUNGER < 103)) {
    tell("You feel yourself growing weaker. Without nourishment, this is a losing cause!\n");
    return true;
  } else if (g.HUNGER > 140) {
    return (await JIGS_UP("You fall over on your face, dreaming of Thanksgiving dinner. Needless to say, it was you against hunger. And hunger won."));
  } else {
    return false;
  }
}

async function I_PARACHUTE() {
  if (g.MOVES < 3) {
    if (await IN_A_TENT$()) {
      tell("\nYou hear a plane flying high overhead, outside the tent.\n");
    } else {
      tell("\nYou crane your neck and see a plane, high overhead, circling the encampment.\n");
    }
    return true;
  } else if (g.MOVES < 5) {
    if (await IN_A_TENT$()) {
      tell("\nIt sounds as if the plane is circling.\n");
    } else {
      tell("\nThe plane seems to be circling right overhead.\n");
    }
    return true;
  } else if (g.MOVES == 5) {
    if (!(await IN_A_TENT$())) {
      tell("\nYou look up to see a small speck appear right beneath the plane -- probably a parachute. The plane heads off far to the northwest, dipping its wings in a salute.\n");
    } else {
      tell("\nIt sounds as if the plane is flying off.\n");
    }
    return true;
  } else if (g.MOVES == 6) {
    if (!(await IN_A_TENT$())) {
      tell("\nA small speck descending from the plane overhead gets larger until you see a crate, dangling from a parachute.\n");
    } else {
      tell("\nYou can barely hear the plane.\n");
    }
    return true;
  } else if (g.MOVES == 7) {
    if (await IN_A_TENT$()) {
      move(CRATE, await RANDOM_ELEMENT(g.ROOM_LTBL));
      tell("\nThe sound of something heavy landing comes from nearby.\n");
    } else {
      tell("\nAt last, your luck seems to be changing. A large crate lands right before you, its parachute flapping in the breeze. The parachute breaks away from the crate and drifts off in the wind.\n");
      move(CRATE, g.HERE);
    }
    setFlag(CRATE, VEHBIT);
    disable(await INT(I_PARACHUTE.id));
    return true;
  } else {
    return false;
  }
}

async function IN_A_TENT$(cot_too$ = true) {
  if (cot_too$) {
    if (eq(loc(g.WINNER), TENT, TENT2, SUPPLY_TENT) || eq(loc(g.WINNER), COT)) {
      return true;
    } else {
      return false;
    }
  } else if (!cot_too$) {
    if (eq(loc(g.WINNER), TENT, TENT2, SUPPLY_TENT)) {
      return true;
    } else {
      return false;
    }
  } else {
    return false;
  }
}

async function RANDOMIZE_HOLES() {
  let offs = 0, max = 0;
  max = get(g.RANDOM_ROOM_LTBL, 0);
  for (;;) {
    offs = offs + 1;
    if (offs > max) {
      return true;
    } else {
      putProp(get(g.RANDOM_ROOM_LTBL, offs), P.CAPACITY, random(2));
    }
  }
}

async function PLANE_FCN() {
  if (!(g.GAME_FLAG == 3)) {
    tell("What plane?\n");
    return true;
  } else if (isVerb(V.WAVE)) {
    if ((g.MOVES < 8) && !(await IN_A_TENT$())) {
      tell("The plane dips its wings in salute.\n");
      return true;
    } else if (g.MOVES < 8) {
      tell("You wave at the plane through the top of the tent. Somehow, I doubt it noticed.\n");
      return true;
    } else {
      tell("The plane's returned to its home base.\n");
      return true;
    }
  } else if (isVerb(V.FIND)) {
    if (g.MOVES > 8) {
      tell("I suppose it's up in the air, somewhere.\n");
      return true;
    } else {
      tell("It's somewhere up over your head.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if (!(await IN_A_TENT$()) && (g.MOVES < 8)) {
      return false;
    } else if (g.MOVES < 8) {
      tell("All I can tell you about it is that it's out there.\n");
      return true;
    } else {
      tell("The plane's far gone, amigo.\n");
      return true;
    }
  } else if (isVerb(V.LISTEN) && (g.MOVES < 9)) {
    tell("RRRRRRRrrrrrrr r r r r r   r    r     r.\n");
    return true;
  } else {
    if (g.MOVES > 8) {
      tell("What plane? It's gone!\n");
    } else {
      tell("Leave the plane alone. It's not bothering you.\n");
    }
    return true;
  }
}

async function GOOD_LUCK_FCN() {
  if (isVerb(V.FIND)) {
    if (g.MOVES < 8) {
      tell("Look up!\n");
      return true;
    } else {
      tell("It's gone with the wind, never to be seen again.\n");
      return true;
    }
  } else if (isVerb(V.EXAMINE)) {
    if ((g.MOVES > 4) && (g.MOVES < 8)) {
      tell("It's white.\n");
      return true;
    } else if (g.MOVES < 5) {
      tell("What parachute?\n");
      return true;
    } else {
      tell("The most I can tell you is that it was white.\n");
      return true;
    }
  } else if (isVerb(V.STAND_UNDER)) {
    return false;
  } else {
    if (g.MOVES > 7) {
      tell("Forget the chute, amigo. It's history. And if you don't get on with this, you will be too.\n");
    } else {
      tell("Leave the parachute alone.\n");
    }
    return true;
  }
}

async function SAND_FCN() {
  if (isVerb(V.BOARD, V.CLIMB_ON, V.SIT_DOWN)) {
    tell("That would be uncomfortable.\n");
    return true;
  } else {
    return false;
  }
}

async function HOLE_FCN() {
  if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    if ((g.HERE == P8) && (loc(PYRAMID) == g.HERE)) {
      tell("You can see the block and the opening in there.\n");
      return true;
    } else if (getProp(g.HERE, P.CAPACITY) > 0) {
      tell(S(g.STUPID_HOLE_JOKE), "\n");
      return true;
    } else {
      tell("I don't see any hole here.\n");
      return true;
    }
  } else if (isVerb(V.FIND)) {
    if (getProp(g.HERE, P.CAPACITY)) {
      tell("It's right here.\n");
      return true;
    } else {
      return false;
    }
  } else if ((g.PRSI == HOLE) && isVerb(V.PUT) && getProp(g.HERE, P.CAPACITY)) {
    tell(S(g.JUST_A_HOLE), "\n");
    return true;
  } else {
    return false;
  }
}

